// Native source transcript search. Source and generated moments stay unchanged.
(()=>{
 const host=document.createElement('section');host.className='panel';host.innerHTML='<h2>Find a passage in the transcript</h2><p class="muted">Load a saved transcript, import full-source subtitles, or explicitly generate a local transcript. Full-source recognition can take time. Search phrases, then choose a passage or select its first and last word.</p><div class="controls"><button id="tr-load">Load saved transcript</button><button id="tr-generate">Generate full-source transcript</button></div><details><summary>Import full-source subtitle text</summary><label>Source subtitle contents<textarea id="tr-text" rows="5" placeholder="Paste full-source SRT / ASS / WebVTT"></textarea></label><button id="tr-import">Import source transcript</button></details><div class="controls"><label>Search transcript<input id="tr-query" placeholder="Find a phrase, name or topic"></label><button id="tr-search">Search passages</button><button id="tr-all">Browse transcript</button></div><p id="tr-note" role="status">Load a source video first.</p><div id="tr-results"></div><div class="controls"><button id="tr-prev" disabled>Previous passages</button><button id="tr-next" disabled>Next passages</button></div>';
 $('style-panel').before(host);let track=null,selected=null,pageOffset=0,pageQuery="";
 const note=text=>$('tr-note').textContent=text;
 function ensure(){if(!id)throw Error('Load a source video first.');if(track&&track.source_id!==id)throw Error('Source changed. Load its transcript first.');}
 function choose(first,last){ensure();const subset=track.words.slice(first,last+1);if(!subset.length)return;const a=subset[0].start,b=subset[subset.length-1].end;if(b-a>600)throw Error('Select a passage shorter than ten minutes.');setRange(a,b);editingClip=null;$('saved-edit').hidden=true;words=subset.map(word=>({...word,start:Math.max(0,word.start-a),end:Math.min(b-a,word.end-a)}));wordRange=signature();renderWords();$('captions').checked=true;v.currentTime=a;note('Selected '+a.toFixed(2)+'–'+b.toFixed(2)+' seconds. Caption timings reused. Review and export.');}
 async function show(query='',offset=0){
  ensure();if(!track)throw Error('Load, import or generate the source transcript first.');
  const data=await request('/transcripts/search',{key:track.key,query,offset});pageOffset=offset;pageQuery=query;$('tr-prev').disabled=offset===0;$('tr-next').disabled=!data.has_more;$('tr-results').replaceChildren();selected=null;
  for(const match of data.matches){const row=document.createElement('div');row.className='transcript-passage';const label=document.createElement('b');label.textContent=match.start.toFixed(1)+'–'+match.end.toFixed(1)+'s';row.append(label);
   const text=document.createElement('p');text.textContent=match.text;row.append(text);const use=document.createElement('button');use.textContent='Use this passage';use.onclick=()=>{try{choose(match.first,match.last);}catch(error){note(error.message);}};row.append(use);
   const detail=document.createElement('details');const title=document.createElement('summary');title.textContent='Choose exact first and last word';detail.append(title);
   track.words.slice(match.first,match.last+1).forEach((word,offset)=>{const button=document.createElement('button');button.className='chip';button.textContent=word.text;button.title=word.start.toFixed(2)+'s';button.onclick=()=>{try{const index=match.first+offset;if(selected===null){selected=index;button.classList.add('active');note('First word selected. Click the last word.');}else{choose(Math.min(selected,index),Math.max(selected,index));selected=null;host.querySelectorAll('.chip.active').forEach(element=>element.classList.remove('active'));}}catch(error){note(error.message);}};detail.append(button);});row.append(detail);$('tr-results').append(row);
  }
  note(data.matches.length+' passages shown (maximum '+data.limit+'). '+track.origin+'.');
 }
 async function load(generate){if(!id)throw Error('Load a source video first.');const sourceId=id;note(generate?'Generating the full-source transcript locally…':'Loading cached transcript…');const result=await request('/transcripts/load',{id:sourceId,language:$('language').value,generate});let record=result.transcript;
  if(result.missing){track=null;note('No saved full-source transcript. Import subtitles or click Generate full-source transcript.');return;}
  if(result.job){for(;;){const state=await request('/status/'+result.job);if(state.status==='error')throw Error(state.error);if(state.status==='done'){record=state.transcript;break;}note(state.message||'Transcribing full source…');await sleep(1000);}}
  if(sourceId!==id)throw Error('Source changed; load its transcript again.');track=record;await show();
 }
 const run=fn=>async()=>{try{await fn();}catch(error){note(error.message);}};
 $('tr-load').onclick=run(()=>load(false));$('tr-generate').onclick=run(()=>load(true));
 $('tr-import').onclick=run(async()=>{if(!id)throw Error('Load a source video first.');const sourceId=id;const imported=await request('/transcripts/import',{id:sourceId,language:$('language').value,text:$('tr-text').value});if(id!==sourceId)throw Error('Source changed.');track=imported;await show();});
 $('tr-prev').onclick=run(()=>show(pageQuery,Math.max(0,pageOffset-100)));$('tr-next').onclick=run(()=>show(pageQuery,pageOffset+100));$('tr-search').onclick=run(()=>show($('tr-query').value));$('tr-all').onclick=run(()=>show());$('tr-query').onkeydown=event=>{if(event.key==='Enter')$('tr-search').click();};
})();
